<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);
require dirname(__DIR__).'/src/database.php';require dirname(__DIR__).'/app/Security/Authenticator.php';require dirname(__DIR__).'/app/Security/UserManagement.php';require dirname(__DIR__).'/app/Security/StripeSecurity.php';
$config=bmaConfig();if(($config['APP_ENV']??'')!=='test'||!str_starts_with($config['DB_DATABASE'],'bma_schema_test_'))throw new RuntimeException('Disposable test database required.');$db=bmaDatabase($config);$checks=0;
ob_start();
function authCheck(bool $ok,string $label):void{global $checks;if(!$ok)throw new RuntimeException('FAIL '.$label);$checks++;echo 'PASS '.$label.PHP_EOL;}
ini_set('session.use_strict_mode','1');session_start();$tag=bin2hex(random_bytes(6));$password=bin2hex(random_bytes(18));$email='security-'.$tag.'@example.invalid';$viewerEmail='viewer-'.$tag.'@example.invalid';$users=new UserManagement($db);$auth=new Authenticator($db,$config);$admin=$users->create($email,'Security fixture','admin',$password);$viewer=$users->create($viewerEmail,'Viewer fixture','viewer',$password);
try{
    $q=$db->prepare('SELECT password_hash FROM app_users WHERE id=?');$q->execute([$admin]);$hash=$q->fetchColumn();authCheck($hash!==$password&&password_verify($password,$hash),'password stored only as verifiable hash');
    foreach(['short',str_repeat('x',73)] as $bad){$rejected=false;try{Passwords::hash($bad);}catch(InvalidArgumentException){$rejected=true;}authCheck($rejected,'password policy rejects unsafe length');}
    $before=session_id();authCheck($auth->login($email,$password,'192.0.2.11'),'valid login');authCheck(session_id()!==$before,'login regenerates session identifier');authCheck($auth->current()['role']==='admin','current user reloaded from database');
    $_SESSION['auth']['last_seen']=time()-4000;authCheck($auth->current()===null,'idle expiration invalidates session');authCheck($auth->login($email,$password,'192.0.2.11'),'login after expiry');$_SESSION['auth']['started']=time()-40000;authCheck($auth->current()===null,'absolute expiration invalidates session');
    authCheck($auth->login($viewerEmail,$password,'192.0.2.12'),'viewer can sign in');$users->update($admin,$viewer,'viewer',false);authCheck($auth->current()===null,'deactivation revokes existing session');authCheck(!$auth->login($viewerEmail,$password,'192.0.2.12'),'disabled user cannot sign in');$users->update($admin,$viewer,'viewer',true);authCheck($auth->login($viewerEmail,$password,'192.0.2.12'),'reactivated viewer login');$resetPassword=bin2hex(random_bytes(18));$users->reset($viewerEmail,$resetPassword);authCheck($auth->current()===null,'CLI password reset revokes sessions');
    $freshIp='192.0.2.13';for($i=0;$i<5;$i++)authCheck(!$auth->login($email,'wrong',$freshIp),'invalid password generic failure');authCheck(!$auth->login($email,$password,$freshIp),'account throttle blocks correct password after limit');
    $token=hash_hmac('sha256','email:'.$email,$config['APP_KEY']);$q=$db->prepare('SELECT attempt_count FROM auth_throttle WHERE bucket_hash=?');$q->execute([$token]);authCheck((int)$q->fetchColumn()===5,'persistent throttle bound after blocked request');
    $otherAdmins=(int)$db->query("SELECT COUNT(*) FROM app_users WHERE role='admin' AND is_active=1 AND id<>".$admin)->fetchColumn();if($otherAdmins===0){$rejected=false;try{$users->update($admin,$admin,'viewer',false);}catch(InvalidArgumentException){$rejected=true;}authCheck($rejected,'last active administrator cannot be disabled or demoted');}
    $ipAuth=new Authenticator($db,array_replace($config,['LOGIN_IP_MAX_ATTEMPTS'=>1]));authCheck(!$ipAuth->login('no-account-'.$tag.'@example.invalid','wrong','192.0.2.14'),'first per-IP failure recorded');authCheck(!$ipAuth->login($viewerEmail,$resetPassword,'192.0.2.14'),'IP throttle spans different accounts');
    $body=json_encode(['id'=>'evt_fixture','object'=>'event','type'=>'test.security'],JSON_THROW_ON_ERROR);$secret='whsec_'.bin2hex(random_bytes(16));$time=time();$signature='t='.$time.',v1='.hash_hmac('sha256',$time.'.'.$body,$secret);$event=StripeSecurity::verify($body,$signature,['STRIPE_WEBHOOK_SECRET'=>$secret]);authCheck($event->id==='evt_fixture','official SDK accepts correct raw-body signature');
    foreach([[$body.' ', $signature],[$body,'t='.$time.',v1=bad'],[$body,'t='.($time-1000).',v1='.hash_hmac('sha256',($time-1000).'.'.$body,$secret)]] as [$payload,$sig]){$rejected=false;try{StripeSecurity::verify($payload,$sig,['STRIPE_WEBHOOK_SECRET'=>$secret]);}catch(Throwable){$rejected=true;}authCheck($rejected,'invalid modified or stale webhook rejected');}
    authCheck(StripeSecurity::client(['STRIPE_API_KEY'=>'rk_test_'.bin2hex(random_bytes(16))]) instanceof Stripe\StripeClient,'restricted-key StripeClient instantiation without network');$rejected=false;try{StripeSecurity::client(['STRIPE_API_KEY'=>'sk_test_'.bin2hex(random_bytes(16))]);}catch(Throwable){$rejected=true;}authCheck($rejected,'unrestricted Stripe key refused');
    Security::log($config,'TEST_ERROR');$log=file_get_contents($config['APP_ERROR_LOG']);authCheck(!str_contains($log,$password)&&str_contains($log,'TEST_ERROR'),'private application log contains codes without passwords');
    $q=$db->prepare("SELECT COUNT(*) FROM audit_log WHERE entity_type='application_security' AND entity_id IN (?,?)");$q->execute([(string)$admin,(string)$viewer]);authCheck((int)$q->fetchColumn()>=6,'account changes and login successes audited');
}finally{
    $_SESSION=[];session_destroy();$db->prepare("DELETE FROM audit_log WHERE entity_type='application_security' AND (entity_id IN (?,?) OR actor_user_id IN (?,?))")->execute([(string)$admin,(string)$viewer,$admin,$viewer]);$db->prepare('DELETE FROM app_users WHERE id IN (?,?)')->execute([$admin,$viewer]);foreach(['email:'.$email,'email:'.$viewerEmail,'ip:192.0.2.11','ip:192.0.2.12','ip:192.0.2.13','ip:192.0.2.14','email:no-account-'.$tag.'@example.invalid'] as $bucket)$db->prepare('DELETE FROM auth_throttle WHERE bucket_hash=?')->execute([hash_hmac('sha256',$bucket,$config['APP_KEY'])]);
}
echo "$checks security checks passed\n";
